function validate([m, n, maxMove, startRow, startColumn]) {
  if (![m, n, maxMove, startRow, startColumn].every(Number.isInteger)) return 'All five values are whole numbers.';
  if (m < 1 || m > 50 || n < 1 || n > 50) return 'm and n are between 1 and 50.';
  if (maxMove < 0 || maxMove > 50) return 'maxMove is between 0 and 50.';
  if (startRow < 0 || startRow >= m) return 'startRow must be a row of the grid.';
  if (startColumn < 0 || startColumn >= n) return 'startColumn must be a column of the grid.';
  return null;
}

