function findPaths(m, n, maxMove, startRow, startColumn) {
  // Top-down: paths out from (r, c) with left moves remaining, memoised.
  const memo = new Map();
  const walk = (r, c, left) => {
    if (r < 0 || c < 0 || r >= m || c >= n) return 1;
    if (left === 0) return 0;
    const key = (r * 64 + c) * 64 + left;
    if (memo.has(key)) return memo.get(key);
    const total = (walk(r + 1, c, left - 1) + walk(r - 1, c, left - 1) + walk(r, c + 1, left - 1) + walk(r, c - 1, left - 1)) % 1000000007;
    memo.set(key, total);
    return total;
  };
  return walk(startRow, startColumn, maxMove);
}

